import {api,escapeHTML as esc,mountGallery} from './common.js?v=20260924c';
import {localStorageStatus,exportLocalBackup,importLocalBackup} from './pages-api.js?v=20260924c';
const el=id=>document.getElementById(id);let stations=[],current=null,token=0,busy=false,dirty=false,gallery=null,pending=[];
const coordDiff=s=>s.masterNotes?.some(n=>n.includes('พิกัด'));
function renderList(){const q=el('master-search').value.toLocaleLowerCase('th').trim(),p=el('master-province').value,diff=el('only-differences').checked;const filtered=stations.filter(s=>(p==='all'||s.province===p)&&(!diff||coordDiff(s))&&[s.displayName,s.name,s.province,s.district,s.subdistrict].join(' ').toLocaleLowerCase('th').includes(q));el('master-list-count').textContent=`แสดง ${filtered.length} จาก 85 จุด`;el('photo-coverage').textContent=`มีรูปแล้ว ${stations.filter(s=>s.photoCount>0).length} / 85 จุด`;el('master-list').innerHTML=filtered.length?filtered.map(s=>`<button class="master-item ${current?.id===s.id?'active':''}" data-id="${s.id}" ${busy?'disabled':''}><strong>${esc(s.displayName)}</strong><span class="meta"><span>${esc(s.province)} · Class ${s.class}</span><span>${s.photoCount} รูป${coordDiff(s)?' · พิกัดต่าง':''}</span></span></button>`).join(''):'<div class="master-empty">ไม่พบจุดที่ตรงกับเงื่อนไข</div>';}
function message(text,error=false){const m=el('master-message');if(!m)return;m.textContent=text;m.classList.toggle('error-text',error);m.setAttribute('role',error?'alert':'status');}
async function refreshStorageStatus(){try{const s=await localStorageStatus();el('master-storage-text').textContent=`บันทึกแล้ว ${s.photoCount} รูปในเบราว์เซอร์นี้ · ${s.persistent?'พื้นที่เก็บถาวรเปิดใช้งานแล้ว':'เบราว์เซอร์ยังไม่ยืนยันพื้นที่เก็บถาวร'} · deploy รุ่นใหม่จะไม่ลบรูป`;}catch{el('master-storage-text').textContent='ตรวจสอบพื้นที่เก็บข้อมูลไม่สำเร็จ';}}
function downloadBackup(blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`station-class-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setupBackup(){el('backup-photos').onclick=async()=>{try{el('backup-photos').disabled=true;message('กำลังสร้างไฟล์สำรองรูปภาพ…');downloadBackup(await exportLocalBackup());message('ดาวน์โหลดไฟล์สำรองแล้ว เก็บไฟล์นี้ไว้ก่อนย้ายเครื่องหรือล้างข้อมูลเบราว์เซอร์');}catch(e){message(e.message,true);}finally{el('backup-photos').disabled=false;}};el('restore-photos').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(!confirm(`กู้คืนรูปและข้อมูล Master จาก ${file.name} ใช่หรือไม่?`)){e.target.value='';return;}try{const r=await importLocalBackup(file);stations=(await api('/api/stations')).stations;renderList();if(current)await choose(current.id);await refreshStorageStatus();message(`กู้คืนรูป ${r.imported} รูปแล้ว`);}catch(err){message(err.message,true);}finally{e.target.value='';}};}
function setBusy(v){busy=v;el('master-editor').querySelectorAll('#master-form button,#master-form input,#master-form textarea,#photo-actions button,#photo-actions input,.upload-zone button,.upload-zone input').forEach(b=>b.disabled=v);renderList();}
function updateStation(s){current=s;const index=stations.findIndex(x=>x.id===s.id);stations[index]={...stations[index],...s,photoCount:s.photos.length};renderList();}
async function choose(id){if(busy)return;if(dirty&&!confirm('มีข้อมูลที่ยังไม่บันทึก ต้องการเปลี่ยนจุดและทิ้งข้อมูลที่แก้ไว้หรือไม่?'))return;dirty=false;pending=[];const t=++token;el('master-editor').innerHTML='<div class="master-loading">กำลังโหลดข้อมูลจุดติดตั้ง…</div>';try{const s=await api('/api/stations/'+id);if(t!==token)return;current=s;history.replaceState(null,'','master.html?station='+id);renderEditor();renderList();}catch(e){if(t===token){el('master-editor').innerHTML=`<p class="error-text">${esc(e.message)}</p><button id="reload-station" class="outline">ลองใหม่</button>`;el('reload-station').onclick=()=>choose(id);}}}
function renderGallery(){gallery=mountGallery(el('master-gallery'),current.photos,{empty:'ยังไม่มีรูปภาพ แนบรูปสถานที่จริงได้ด้านล่าง',onChange:p=>{el('photo-actions').hidden=!p;el('photo-caption-input').value=p?.caption??'';}});}
function renderEditor(){const s=current;el('master-editor').innerHTML=`<span class="class-badge ${s.class}">Class ${s.class}</span><h2 style="margin-top:12px">${esc(s.displayName)}</h2><p class="small muted">ต.${esc(s.subdistrict)} อ.${esc(s.district)} จ.${esc(s.province)} · สถานี${esc(s.status)}</p><div class="coordinates"><div><small>ละติจูดจาก Excel</small>${s.lat}</div><div><small>ลองจิจูดจาก Excel</small>${s.lon}</div></div><div class="master-source"><details ${coordDiff(s)?'open':''}><summary>${coordDiff(s)?'พิกัดในรายการแนบต่างจาก Excel':'ดูข้อมูลต้นฉบับและการจับคู่'}</summary><p>ชื่อ Excel: ${esc(s.name)}<br>รายการแนบ: ${esc(s.masterName)}<br>พิกัดรายการแนบ: ${esc(s.providedLat)}, ${esc(s.providedLon)}<br>UTM ในรายการแนบ: ${esc(s.masterUTM)}${coordDiff(s)?'<br><strong>UTM นี้มาจากรายการแนบ จึงไม่ใช้แทนพิกัด Excel บนแผนที่</strong>':''}<br>Excel: ${esc(s.source)} แถว ${s.row} คอลัมน์ G/H<br>รายการแนบแถว ${s.masterSourceRow} · จับคู่ด้วย${esc(s.matchMethod)}</p></details></div><form id="master-form"><label class="form-field">ชื่อสถานที่ที่แสดงใน Master และแผนที่<input id="display-name" required maxlength="250" value="${esc(s.displayName)}"></label><label class="form-field">หมายเหตุสถานที่<textarea id="station-notes" maxlength="6000" placeholder="เช่น ทางเข้า จุดติดตั้ง หรือรายละเอียดประกอบการสำรวจ">${esc(s.notes)}</textarea></label><div class="master-actions"><button class="button-primary" type="submit">บันทึกข้อมูล Master</button><a class="outline" href="index.html?station=${s.id}#map">ดูจุดนี้บนแผนที่ ↗</a><span class="note" id="saved-state">${s.updatedAt?'บันทึกล่าสุด '+new Date(s.updatedAt).toLocaleString('th-TH'):'ยังไม่มีการแก้ข้อมูล Master'}</span></div></form><div id="master-message" role="status"></div><h3>รูปภาพสถานที่ <span class="muted small">${s.photos.length} รูป</span></h3><div class="master-gallery" id="master-gallery"></div><div id="photo-actions" hidden><label class="form-field">คำอธิบายรูปที่กำลังแสดง<input id="photo-caption-input" maxlength="500"></label><div class="photo-actions"><button class="outline" id="save-caption">บันทึกคำอธิบายรูป</button><button class="outline danger" id="delete-photo">ลบรูปนี้</button></div></div><h3>แนบรูปเพิ่ม</h3><div class="upload-zone"><p>เลือกได้หลายรูป • JPEG / PNG / WebP • ไม่เกิน 10 MB ต่อรูป</p><input type="file" id="photo-files" accept="image/jpeg,image/png,image/webp" multiple aria-label="เลือกรูปภาพสถานที่"><p id="pending-count">ยังไม่ได้เลือกรูป</p><button class="button-primary" id="upload-photos">อัปโหลดรูปที่เลือก</button><p id="upload-progress" role="status"></p></div>`;
 renderGallery();el('master-form').addEventListener('input',()=>dirty=true);el('master-form').onsubmit=saveMaster;el('photo-files').onchange=()=>{pending=[...el('photo-files').files];el('pending-count').textContent=pending.length?`เลือก ${pending.length} รูป · ${(pending.reduce((a,f)=>a+f.size,0)/1048576).toFixed(1)} MB`:'ยังไม่ได้เลือกรูป';};el('upload-photos').onclick=uploadPhotos;el('save-caption').onclick=saveCaption;el('delete-photo').onclick=deletePhoto;}
async function saveMaster(e){e.preventDefault();if(busy)return;setBusy(true);message('กำลังบันทึก…');try{const s=await api('/api/stations/'+current.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({displayName:el('display-name').value,notes:el('station-notes').value,revision:current.revision})});updateStation(s);dirty=false;el('master-editor').querySelector('h2').textContent=s.displayName;el('saved-state').textContent='บันทึกแล้ว '+new Date(s.updatedAt).toLocaleString('th-TH');message('บันทึกข้อมูล Master ในเบราว์เซอร์นี้แล้ว');}catch(e){message(e.message,true);}finally{setBusy(false);}}
async function uploadPhotos(){if(busy)return;if(!pending.length){message('กรุณาเลือกรูปภาพก่อนอัปโหลด',true);return;}const invalid=pending.find(f=>f.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type));if(invalid){message(`ไฟล์ ${invalid.name} ไม่ใช่ JPEG/PNG/WebP หรือมีขนาดเกิน 10 MB`,true);return;}setBusy(true);message('กำลังอัปโหลด กรุณารอจนบันทึกครบ');const total=pending.length;let done=0;try{while(pending.length){const file=pending[0];el('upload-progress').textContent=`กำลังบันทึก ${done+1}/${total}: ${file.name}`;const form=new FormData();form.append('file',file);const s=await api('/api/stations/'+current.id+'/photos',{method:'POST',body:form});updateStation(s);pending.shift();done++;}el('photo-files').value='';el('pending-count').textContent='ยังไม่ได้เลือกรูป';renderGallery();el('master-editor').querySelector('h3').innerHTML=`รูปภาพสถานที่ <span class="muted small">${current.photos.length} รูป</span>`;message(`บันทึก ${done} รูปบนเซิร์ฟเวอร์แล้ว เปิดดูจากแผนที่ได้ทันที`);el('upload-progress').textContent='อัปโหลดครบแล้ว';}catch(e){renderGallery();message(`บันทึกแล้ว ${done}/${total} รูป; เหลือ ${pending.length} รูปที่ยังไม่สำเร็จ\n${e.message}`,true);el('pending-count').textContent=`รออัปโหลดต่อ ${pending.length} รูป`;el('upload-progress').textContent='กดอัปโหลดอีกครั้งเพื่อส่งเฉพาะรูปที่เหลือ';}finally{setBusy(false);}}
async function saveCaption(){const p=gallery.current();if(!p||busy)return;setBusy(true);try{await api('/api/photos/'+p.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({caption:el('photo-caption-input').value})});p.caption=el('photo-caption-input').value;const index=current.photos.findIndex(x=>x.id===p.id);renderGallery();gallery.goTo(index);message('บันทึกคำอธิบายรูปแล้ว');}catch(e){message(e.message,true);}finally{setBusy(false);}}
async function deletePhoto(){const p=gallery.current();if(!p||busy||!confirm(`ลบรูป “${p.filename}” ออกจากจุดนี้และเซิร์ฟเวอร์ใช่หรือไม่?`))return;setBusy(true);try{await api('/api/photos/'+p.id,{method:'DELETE'});current.photos=current.photos.filter(x=>x.id!==p.id);updateStation(current);renderGallery();el('master-editor').querySelector('h3').innerHTML=`รูปภาพสถานที่ <span class="muted small">${current.photos.length} รูป</span>`;await refreshStorageStatus();message('ลบรูปภาพแล้ว');}catch(e){message(e.message,true);}finally{setBusy(false);}}
el('master-list').onclick=e=>{const b=e.target.closest('[data-id]');if(b)void choose(Number(b.dataset.id));};el('master-search').oninput=renderList;el('master-province').onchange=renderList;el('only-differences').onchange=renderList;el('show-differences').onclick=()=>{el('only-differences').checked=true;el('master-province').value='all';el('master-search').value='';renderList();};window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});
async function init(){try{setupBackup();await refreshStorageStatus();const data=await api('/api/stations');stations=data.stations;el('master-province').innerHTML='<option value="all">ทุกจังหวัด</option>'+[...new Set(stations.map(s=>s.province))].sort((a,b)=>a.localeCompare(b,'th')).map(p=>`<option>${esc(p)}</option>`).join('');renderList();const id=Number(new URL(location.href).searchParams.get('station'));if(id&&stations.some(s=>s.id===id))await choose(id);}catch(e){el('master-list').innerHTML=`<div class="master-loading error-text">${esc(e.message)}<br><button class="outline" id="retry-master">ลองใหม่</button></div>`;el('photo-coverage').textContent='ยังโหลดข้อมูลไม่ได้';el('retry-master').onclick=init;}}
void init();
